#!/usr/bin/env bash
# Regenerate prometheusrule.yaml (Prometheus Operator CRD) from kevgate-rules.yaml so the two
# never drift. CI runs this and fails on `git diff --exit-code`.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"
{
  cat <<'HDR'
# GENERATED by render-prometheusrule.sh from kevgate-rules.yaml. Do not edit by hand.
# Apply into the kevgate namespace on clusters running the Prometheus Operator
# (kube-prometheus-stack). The release label must match the operator's ruleSelector.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: kevgate
  namespace: kevgate
  labels:
    app.kubernetes.io/name: kevgate
    app.kubernetes.io/part-of: kevgate
    release: kube-prometheus-stack
spec:
HDR
  sed -n '/^groups:/,$p' kevgate-rules.yaml | sed 's/^/  /'
} > prometheusrule.yaml
